import { z } from "zod";

// Generated by the pipeline into public/data/index/. Bump the version when the shape changes.
export const INDEX_SCHEMA_VERSION = 1;

const countryCode = z.string().regex(/^[A-Z]{2}$/, "ISO 3166-1 alpha-2 code");
const imageId = z.string().regex(/^\d+$/, "Mapillary image id");

export const countryListSchema = z.object({
  schema_version: z.literal(INDEX_SCHEMA_VERSION),
  countries: z.array(
    z.object({
      code: countryCode,
      name: z.string().min(1),
      image_count: z.number().int().nonnegative(),
    }),
  ),
});

export const countryIndexSchema = z.object({
  schema_version: z.literal(INDEX_SCHEMA_VERSION),
  country: countryCode,
  name: z.string().min(1),
  // [west, south, east, north] in degrees
  bbox: z.tuple([z.number(), z.number(), z.number(), z.number()]),
  images: z.array(imageId).min(1),
});

export type CountryList = z.infer<typeof countryListSchema>;
export type CountryIndex = z.infer<typeof countryIndexSchema>;
